select     concat(cast(right(floor(tjzq), 2) as int), '月') as month,     cast(right(floor(tjzq), 2) as int) as month_num,     round(sum(case when hkywlx in ('03', '04') then dyhsbj else 0 end) /10000, 2) as tqhk,     round(sum(case when hkywlx not in ('03', '04') then dyhsbj else 0 end) /10000, 2) as zchk from dws_bus_ln_rec_mfm where left(tjzq, 4) = #{ssnd} group by cast(right(floor(tjzq), 2) as int) order by month_num
